// 5.4 — one armor-training source for equip actions, defense selectors and recalculation.
const ARMOR_GROUP54={padded:'light',leather:'light',studded:'light',hide:'medium',chainshirt:'medium',scale:'medium',breastplate:'medium',halfplate:'medium',ring:'heavy',chain:'heavy',splint:'heavy',plate:'heavy',shield:'shield'};
const ARMOR_LABEL54={light:'armaduras leves',medium:'armaduras médias',heavy:'armaduras pesadas',shield:'escudos'};
ARMOR_DATA.padded='Armadura acolchoada';ARMOR_DATA.breastplate='Peitoral';
function armorTraining54(x){const out=new Set();for(const [i,cls]of(x.classes||[]).entries()){if(cls.level<1)continue;const n=cls.name;if(['Guerreiro','Paladino','Patrulheiro','Clérigo'].includes(n)){out.add('light');out.add('medium');out.add('shield');if(i===0&&['Guerreiro','Paladino'].includes(n))out.add('heavy');}else if(n==='Bárbaro'){out.add('shield');if(i===0){out.add('light');out.add('medium');}}else if(['Bardo','Ladino','Bruxo'].includes(n))out.add('light');else if(n==='Druida'){out.add('light');out.add('shield');}if(n==='Bardo'&&cls.level>=3&&x.bookChoices?.subclasses?.Bardo==='475'){out.add('medium');out.add('shield');}}
 const order=x.creationWizard?.extra?.order;if(order==='Protetor'&&x.classes?.some(p=>p.name==='Clérigo'&&p.level>=1))out.add('heavy');if(order==='Guardião'&&x.classes?.some(p=>p.name==='Druida'&&p.level>=1))out.add('medium');
 for(const id of x.bookChoices?.feats||[]){const name=getBook(id)?.name;if(name==='Lightly Armored'){out.add('light');out.add('shield');}if(name==='Moderately Armored')out.add('medium');if(name==='Heavily Armored')out.add('heavy');}return out;
}
function armorItemMode54(item){const text=normBook(getBook(item.bookId)?.name||item.name||'').replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ').trim();if(text==='couro')return 'leather';const names=[['shield',['shield','escudo']],['studded',['studded leather','couro batido']],['halfplate',['half plate','halfplate','meia armadura']],['chainshirt',['chain shirt','camisao de malha']],['breastplate',['breastplate','peitoral']],['padded',['padded','acolchoada','gibao acolchoado']],['leather',['leather armor','armadura de couro']],['hide',['hide armor','gibao de peles']],['scale',['scale mail','brunea','cota de escamas']],['ring',['ring mail','cota de aneis']],['chain',['chain mail','cota de malha']],['splint',['splint','talas']],['plate',['plate armor','placas']]];for(const [mode,aliases]of names)if(aliases.some(name=>(' '+text+' ').includes(' '+name+' ')))return mode;return /\b(?:armor|armour|armadura|cota)\b/.test(text)?'unknown':null;}
function armorAllowed54(x,mode){return mode==='unknown'?false:!ARMOR_GROUP54[mode]||armorTraining54(x).has(ARMOR_GROUP54[mode]);}
function armorBlock54(mode){return mode==='unknown'?'Escolha uma categoria reconhecida de armadura antes de equipar.':'O personagem não tem proficiência com '+ARMOR_LABEL54[ARMOR_GROUP54[mode]]+'.';}
function sanitizeArmor54(x){const training=armorTraining54(x);let changed=false;for(const item of x.play?.inventory||[]){const mode=armorItemMode54(item);if(item.equipped&&mode&&(mode==='unknown'||!training.has(ARMOR_GROUP54[mode]))){item.equipped=false;changed=true;}}if(ARMOR_GROUP54[x.calc.acMode]&&!training.has(ARMOR_GROUP54[x.calc.acMode])){x.calc.acMode='none';changed=true;}if(x.calc.shield&&!training.has('shield')){x.calc.shield=false;changed=true;}if(changed){x.play??={};x.play.armorNotice54='Equipamentos sem a proficiência necessária foram guardados e não entram na CA. Os itens continuam no inventário.';}return changed;}
const recalcBefore54=recalc;
recalc=function(x){initRules(x);sanitizeArmor54(x);const result=recalcBefore54(x);if(['padded','breastplate'].includes(x.calc.acMode)){const dex=mod(x.attrs[1]);x.ac=(x.calc.acMode==='padded'?11+dex:14+Math.min(2,dex))+(x.calc.shield?2:0)+Number(x.calc.acBonus||0);}return result;};
const calcBefore54=calcSet;
calcSet=function(key,value){const mode=key==='acMode'?value:key==='shield'&&value?'shield':null;if(mode&&!armorAllowed54(c(),mode)){toast(armorBlock54(mode));render();return false;}if(key==='acMode'&&value!=='manual')for(const item of playState().inventory){const itemMode=armorItemMode54(item);if(itemMode&&itemMode!=='shield'&&itemMode!==value)item.equipped=false;}return calcBefore54(key,value);};
