const crestBefore510=vitalCrest;
vitalCrest=function(kind,...args){const html=crestBefore510(kind,...args);if(kind!=='ac')return html;const box=document.createElement('div');box.innerHTML=html;const old=box.firstElementChild,button=document.createElement('button');for(const a of old.attributes)button.setAttribute(a.name,a.value);button.removeAttribute('role');button.type='button';button.setAttribute('aria-label','Classe de Armadura: '+c().ac+'. Abrir Defesa');button.setAttribute('aria-haspopup','dialog');button.setAttribute('onclick','openDefense510()');button.innerHTML=old.innerHTML;old.replaceWith(button);return box.innerHTML;};
