function compactModifiers510(){for(const root of document.querySelectorAll('#view .checks59 .global-roll-modifiers,#view .attack-table .global-roll-modifiers')){root.classList.add('compact-modifiers510');root.querySelector('h4')?.remove();root.querySelector('small')?.remove();for(const input of root.querySelectorAll('input[type=checkbox]')){const label=input.closest('label');if(!label)continue;const button=document.createElement('button');button.type='button';button.className='modifier-toggle56';button.setAttribute('aria-pressed',String(input.checked));button.textContent=label.textContent.trim();button.setAttribute('onclick',(input.getAttribute('onchange')||'').replace(/this\.checked/g,String(!input.checked)));label.replaceWith(button);}}}
const SPELL_STAT_ART510={save:'M18 3 31 8v12c0 8-6 13-13 17C11 33 5 28 5 20V8ZM10 18q8-9 16 0-8 9-16 0Zm8-3v6',attack:'M18 2v7m0 22v7M2 20h7m18 0h7M18 6a14 14 0 1 0 .01 0M20 9l-9 13h8l-3 10 11-15h-8Z'};
function decorateSpellStats510(){for(const card of document.querySelectorAll('#view .spell-summary-grid429>div')){const attack=card.querySelector('.spell-attack-roll454')||/Ataque de Magia|Spell Attack/i.test(card.textContent),save=/CD de Salvaguarda|Save DC/i.test(card.textContent);if(!attack&&!save)continue;card.classList.add('spell-stat510',attack?'spell-stat-attack510':'spell-stat-save510');if(!card.querySelector('.spell-stat-art510'))card.insertAdjacentHTML('afterbegin','<svg class="spell-stat-art510" viewBox="0 0 36 40" aria-hidden="true"><path d="'+SPELL_STAT_ART510[attack?'attack':'save']+'"/></svg>');}}
