 compactModifiers510();decorateSpellStats510();
 document.querySelector('.disclaimer')?.remove();
 const band=document.querySelector('#portrait-band'),prof=band?.querySelector('.summary-proficiency-button468');
 if(prof&&!band.querySelector('.summary-links510')){const links=document.createElement('div');links.className='summary-links510';prof.before(links);links.append(prof);links.insertAdjacentHTML('beforeend','<button class="summary-history510" aria-haspopup="dialog" onclick="openHistory510()">História</button>');}
