inventoryView=function(){const p=playState(),items=p.inventory;return `<section class="card inventory526"><h2>Inventário</h2><div class="inventory-bars526">${items.map((item,i)=>{const arg=inventoryArg526(item.id),mode=armorItemMode54(item),blocked=!item.equipped&&mode&&!armorAllowed54(c(),mode),price=inventoryPrice526(item);return `<article class="inventory-bar526 ${item.equipped?'equipped526':''}" data-inventory-id="${esc(item.id)}"><div class="inventory-order526"><button aria-label="Subir ${esc(item.name)}" ${i===0?'disabled':''} onclick="moveInventory526(${arg},-1)">↑</button><button aria-label="Descer ${esc(item.name)}" ${i===items.length-1?'disabled':''} onclick="moveInventory526(${arg},1)">↓</button></div><button class="inventory-name526" title="${esc(item.name)}" aria-haspopup="dialog" onclick="openInventory526(${arg})"><b>${esc(item.name)}</b><small>${inventoryNumber526(item.weight)} lb/unid. · ${price===null?'Valor —':price510(price)+'/unid.'}</small></button><div class="inventory-quantity526"><button aria-label="Diminuir ${esc(item.name)}" onclick="inventoryQuantity(${arg},-1)">−</button><span title="Quantidade">${inventoryNumber526(item.quantity)}<small>unid.</small></span><button aria-label="Aumentar ${esc(item.name)}" onclick="inventoryQuantity(${arg},1)">+</button></div><button class="inventory-equip526" aria-label="Equipado: ${esc(item.name)}" aria-pressed="${Boolean(item.equipped)}" ${blocked?'disabled':''} title="${esc(blocked?armorBlock54(mode):item.equipped?'Guardar item':'Equipar item')}" onclick="inventoryEquip(${arg})"><span aria-hidden="true">${item.equipped?'◆':'◇'}</span><small>${item.equipped?'Equipado':'Equipar'}</small></button></article>`;}).join('')||'<p class="muted">Nenhum item no inventário.</p>'}</div><p class="inventory-weight526">Peso total: <b>${inventoryNumber526(items.reduce((n,e)=>n+Number(e.quantity||0)*Number(e.weight||0),0))} lb</b> · capacidade básica ${c().attrs[0]*(c().species==='Goliath'?30:15)} lb</p><button onclick="openItemPicker()">＋ Adicionar item do catálogo</button>${p.armorNotice54?'<p class="muted armor-notice54" role="status">'+esc(p.armorNotice54)+'</p>':''}</section>`;};
function moveInventory526(id,delta){if(![-1,1].includes(delta))return;const items=playState().inventory,i=items.findIndex(e=>e.id===id),j=i+delta;if(i<0||j<0||j>=items.length)return;[items[i],items[j]]=[items[j],items[i]];save();render();}
function openInventory526(id){const item=playState().inventory.find(e=>e.id===id);if(!item)return;const book=getBook(item.bookId),catalog=inventoryCatalog526(item),price=inventoryPrice526(item),arg=inventoryArg526(id);openPlayDialog(item.name,`<div class="inventory-detail526"><p>${inventoryNumber526(item.quantity)} unidade(s) · ${inventoryNumber526(item.weight)} lb por unidade · ${price===null?'Valor não registrado':price510(price)+' por unidade'}</p><p>Peso total: ${inventoryNumber526(item.weight*item.quantity)} lb${price!==null?' · Valor total: '+price510(price*item.quantity):''}</p><p>${item.equipped?'Equipado':'Guardado'}${catalog?' · '+esc(catalog.category):''}${book?.page?' · Livro, pág. '+book.page:''}</p>${book?.text?'<div class="inventory-description526">'+esc(book.text)+'</div>':'<p class="muted">Sem descrição no catálogo.</p>'}<label>Nome do item<input id="inventory-name526" maxlength="160" value="${esc(item.name)}"></label><button class="primary" onclick="renameInventory526(${arg})">Salvar nome</button><button class="danger" onclick="confirmDeleteInventory526(${arg})">Excluir item</button></div>`);}
function renameInventory526(id){const item=playState().inventory.find(e=>e.id===id),name=document.getElementById('inventory-name526')?.value.trim();if(!item||!name)return toast('Informe o nome do item.');if(name.length>160)return;item.armorMode526=armorItemMode54(item);const price=inventoryPrice526(item);if(price!==null)item.unitCp526=price;item.name=name;save();render();document.getElementById('play-dialog')?.close();}
function releaseArmor526(item){if(!item?.equipped)return;const mode=armorItemMode54(item);if(mode==='shield')c().calc.shield=false;else if(mode&&c().calc.acMode===mode)c().calc.acMode='none';}
function confirmDeleteInventory526(id){const item=playState().inventory.find(e=>e.id===id);if(!item)return;openPlayDialog('Excluir item',`<p>Excluir ${esc(item.name)} e suas ${inventoryNumber526(item.quantity)} unidade(s) do inventário?</p><button class="danger" onclick="deleteInventory526(${inventoryArg526(id)})">Excluir</button><button onclick="openInventory526(${inventoryArg526(id)})">Cancelar</button>`);}
function deleteInventory526(id){const p=playState(),item=p.inventory.find(e=>e.id===id);if(!item)return;releaseArmor526(item);p.inventory=p.inventory.filter(e=>e.id!==id);save();render();document.getElementById('play-dialog')?.close();}
