const calcBefore526=calcSet;
calcSet=function(key,value){const out=calcBefore526(key,value);if(out===false)return out;if(key==='shield'||key==='acMode'&&value!=='manual'){for(const item of playState().inventory){const mode=armorItemMode54(item);if(key==='shield'&&mode==='shield')item.equipped=Boolean(value)&&playState().inventory.find(e=>armorItemMode54(e)==='shield')===item;else if(key==='acMode'&&mode&&mode!=='shield')item.equipped=mode===value&&playState().inventory.find(e=>armorItemMode54(e)===value)===item;}save();render();}return out;};
