function startingChoice533(name,d){const n=normBook(name),extra=d.extra||{};if(/instrumento musical/.test(n))return extra.instrument0||extra.bgInstrument||name;if(/ferramenta de artesao ou instrumento/.test(n))return extra.tool||name;if(/ferramentas de artesao/.test(n))return extra.bgTool||c().customBackground?.tool||name;if(/kit de jogos|jogo escolhido/.test(n))return extra.gaming||name;return name;}
function startingItem533(raw,d){let name=startingChoice533(raw,d),quantity=1;const prefix=name.match(/^(\d+)\s+(.+)$/);if(prefix){quantity=+prefix[1];name=prefix[2];}const suffix=name.match(/^(Óleo|Pergaminho)\s*\((\d+)\s+(?:frascos|folhas)\)$/i);if(suffix){quantity=+suffix[2];name=normBook(suffix[1])==='oleo'?'Óleo (frasco)':'Pergaminho (folha)';}const n=normBook(name);name=ITEM_ALIASES533[n]||name;const bookName=/^livro\s*\(/i.test(name)?'Livro':name;const item=SHOP_ITEMS510.find(e=>normBook(e.name)===normBook(bookName)||normBook(e.en||'')===normBook(bookName));const ammo=/^(Flechas|Virotes) \(20\)$/.test(name);const book=!item?wentries('Equipamento').find(e=>normBook(e.name)===normBook(name)||name==='Grimório'&&e.name==='Spellbook'):null;return {name:ammo?name.replace(' (20)',''):item&&bookName===name?item.name:name,quantity,weight:item?item.weight/(ammo?20:1):name==='Grimório'?3:0,...(item?{shopSku510:item.sku+(ammo?'-individual':''),unitCp526:item.cp/(ammo?20:1),...(item.bookId?{bookId:item.bookId}:{})}:book?{bookId:book.id}:{}),...(name==='Grimório'?{unitCp526:5000}:{}),weapon:item?.en&&WEAPON_DATA.some(w=>w.en===item.en)?item.en:/foco.*cajado/.test(normBook(name))?'Quarterstaff':null};}
function startingLines533(d){const rule=W_CLASS[d.cls],groups=[];if(!rule)return groups;const add=(text,source)=>{const choices=source.startsWith('Antecedente')?{...d,extra:{...d.extra,instrument0:undefined}}:d;for(const raw of text.split(';').map(v=>v.trim()).filter(Boolean)){if(/^\d+\s*(?:PO|GP|CP)$/i.test(raw))continue;const pack=PACK_ALIASES533[normBook(raw)];if(pack){for(const [name,quantity]of PACK_CONTENTS533[pack])groups.push({...startingItem533(name,choices),quantity,source:source+' · '+raw});}else groups.push({...startingItem533(raw,choices),source});}};if(d.classKit!=='gold')add(d.classKit==='B'?rule.alt||rule.kit:rule.kit,'Classe · '+d.cls);if(d.bgKit!=='gold'){const bg=getBook(d.background),items=backgroundItems453(bg);if(items?.length)add(items.join('; '),'Antecedente · '+(bg?.name||''));}return groups;}
syncStartingEquipment=function(){const d=c()?.creationWizard;if(!d?.cls)return;const p=playState(),lines=startingLines533(d),signature=JSON.stringify(['5.33',d.cls,d.background,d.classKit,d.bgKit,lines]);if(p.starterSignature===signature)return;const inventory=p.inventory.filter(e=>!e.starter),weapons=p.weapons.filter(e=>!e.starter),byItem=new Map(),weaponNames=new Set(weapons.map(e=>e.weapon));for(const line of lines){const key=(line.shopSku510||line.bookId||line.name)+'|'+line.name;let item=byItem.get(key);if(item){item.quantity+=line.quantity;if(!item.startingSources533.includes(line.source))item.startingSources533.push(line.source);}else{const {weapon,source,...data}=line;item={id:crypto.randomUUID(),...data,starter:true,startingSources533:[source],equipped:false};const mode=armorItemMode54(item);item.equipped=Boolean(line.weapon||mode&&armorAllowed54(c(),mode));byItem.set(key,item);inventory.push(item);}if(line.weapon&&!weaponNames.has(line.weapon)){weapons.push({id:crypto.randomUUID(),weapon:line.weapon,ability:'auto',magic:0,proficient:'auto',two:false,offhand:false,starter:true});weaponNames.add(line.weapon);}}p.inventory=inventory;p.weapons=weapons;p.starterSignature=signature;};
