function inventoryPack534(entry){if(!entry)return null;if(PACK_SHOP534[entry.sku])return PACK_SHOP534[entry.sku];const name=normBook(entry.name).replace(/[’']/g,'').replace(/\s*\([^)]*\)\s*/g,'').trim();const aliases={'burglars pack':'burglar','diplomats pack':'diplomat','dungeoneers pack':'dungeon','entertainers pack':'entertainer','explorers pack':'explorer','priests pack':'priest','scholars pack':'scholar','kit de artista':'entertainer','kit de assaltante':'burglar','kit de aventureiro':'explorer','kit de diplomata':'diplomat','kit de erudito':'scholar','kit de explorador de masmorras':'dungeon','kit de sacerdote':'priest'};return aliases[name]||PACK_ALIASES533[name]||null;}
const itemPickerBefore534=openItemPicker;
openItemPicker=function(){const shop=SHOP_ITEMS510.map(e=>`<option value="shop:${esc(e.sku)}">${esc(e.name)}${inventoryPack534(e)?' · itens individuais':''}</option>`),extras=wentries('Equipamento').filter(e=>!SHOP_ITEMS510.some(s=>s.bookId===e.id||normBook(s.name)===normBook(e.name)||s.en&&normBook(s.en)===normBook(e.name)));openPlayDialog('Adicionar equipamento',`<p class="muted">Pacotes são separados em seus componentes, com as quantidades de cada item.</p><label>Item<select id="inventory-item">${shop.join('')}${extras.map(e=>`<option value="${esc(e.id)}">${esc(e.name)}${inventoryPack534(e)?' · itens individuais':''}</option>`).join('')}</select></label><button class="primary" onclick="addInventoryItem(document.querySelector('#inventory-item').value)">Adicionar à mochila</button>`);enhanceSelects(document.querySelector('#play-dialog'));};
const addInventoryBefore534=addInventoryItem;
addInventoryItem=function(id){const shop=String(id).startsWith('shop:')?SHOP_ITEMS510.find(e=>e.sku===String(id).slice(5)):null,entry=shop||getBook(id);if(!entry||!shop&&entry.kind!=='Equipamento')return;const pack=inventoryPack534(entry);if(!pack&&!shop)return addInventoryBefore534(id);const lines=pack?PACK_CONTENTS533[pack].map(([name,quantity])=>({...startingItem533(name,{extra:{}}),quantity})): [{name:shop.name,quantity:1,weight:shop.weight,shopSku510:shop.sku,unitCp526:shop.cp,...(shop.bookId?{bookId:shop.bookId}:{})}];const p=playState(),previous=p.inventory,next=p.inventory.map(e=>({...e}));try{for(const line of lines){const {weapon,...data}=line;const old=next.find(e=>!e.starter&&e.name===data.name&&e.weight===data.weight&&(data.shopSku510?e.shopSku510===data.shopSku510:e.bookId===data.bookId));if(old){if(!Number.isSafeInteger(old.quantity)||old.quantity<0||!Number.isSafeInteger(old.quantity+data.quantity))throw Error('Confira a quantidade de '+data.name+'.');old.quantity+=data.quantity;}else next.push({id:crypto.randomUUID(),...data,equipped:false});}p.inventory=next;try{localStorage.setItem('codice2024',JSON.stringify(db,function(k,v){return k==='data'&&this.storageKey?undefined:v;}));}catch{p.inventory=previous;throw Error('Não foi possível salvar. O inventário foi mantido.');}document.querySelector('#saved').textContent='Tudo salvo';render();document.querySelector('#play-dialog')?.close();toast(pack?'Componentes do pacote adicionados ao inventário.':'Item adicionado ao inventário.');}catch(error){toast(error.message);}};

const equipWithoutManager536=inventoryEquip;
