let equipPending535=null;
function equipWeapon535(item){const cat=inventoryCatalog526(item),name=normBook(getBook(item.bookId)?.name||item.name);return WEAPON_DATA.find(w=>w.en===cat?.en||normBook(w.name)===name||normBook(w.en)===name)||(/foco.*cajado/.test(normBook(item.name))?WEAPON_DATA.find(w=>w.en==='Quarterstaff'):null);}
function equipType535(item){const mode=armorItemMode54(item);if(mode==='shield')return 'shield';if(mode&&mode!=='unknown')return 'armor';if(equipWeapon535(item))return 'weapon';if(!inventoryCatalog526(item)&&!item.bookId&&(Object.hasOwn(EQUIP_SLOTS535,item.equipType535)||item.equipType535==='held'))return item.equipType535;const n=normBook(item.name);if(/\b(elmo|helmet|hat|chapeu|capuz|coroa|tiara|circlet)\b/.test(n))return 'head';if(/\b(botas?|sapatos?|sandalias?|boots?|shoes?)\b/.test(n))return 'feet';if(/\b(cachecol|scarf)\b/.test(n))return 'scarf';if(/\b(capa|manto|cloak|cape)\b/.test(n))return 'cape';if(/\b(bracadeiras?|braceletes?|bracers?)\b/.test(n))return 'bracers';if(/\b(aneis|anel|rings?)\b/.test(n))return 'rings';if(/\b(colar|colares|necklace|amuleto|relicario|pendant|simbolo sagrado)\b/.test(n))return 'necklaces';if(/\b(tocha|lanterna|lampada|torch|lantern|foco|varinha|orbe|wand|orb|livro|grimorio)\b/.test(n))return 'held';if(!inventoryCatalog526(item)&&!item.bookId&&(Object.hasOwn(EQUIP_SLOTS535,item.equipType535)||item.equipType535==='held'))return item.equipType535;return null;}
function equipOptions535(item){const type=equipType535(item),w=equipWeapon535(item);if(type==='weapon'&&/\btwo\b/.test(w?.props||''))return ['both'];if(['weapon','shield','held'].includes(type))return w&&/versatile:/.test(w.props)?['right','left','both']:['right','left'];return EQUIP_SLOTS535[type]?[type]:[];}
