function equipmentManager535(){return `<section class="card equipment-manager535"><h2>Equipamentos</h2><p class="muted">Toque na figura ou em um espaço para equipar e guardar itens.</p><div class="equipment-layout535">${equipmentFigure535()}<div class="equipment-slots535">${Object.entries(EQUIP_SLOTS535).map(([slot,label])=>{const items=equipIds535(slot);return `<button class="equipment-slot535 ${items.length?'occupied535':''}" onclick="openEquipmentSlot535('${slot}')"><span>${label}${['rings','necklaces'].includes(slot)&&items.length?' · '+items.length:''}</span><b>${items.map(e=>esc(e.name)).join(' · ')||'Livre'}</b></button>`;}).join('')}</div></div></section>`;}
