function setEquipType535(id,type){const item=playState().inventory.find(e=>e.id===id);if(!item||type&&!EQUIP_SLOTS535[type])return;persistEquipment535(()=>{item.equipped=false;item.equipSlots535=[];item.equipType535=type;});}
