function createCustomEquipment535(slot){if(!EQUIP_SLOTS535[slot]||['armor','right','left'].includes(slot))return;const name=document.querySelector('#custom-equipment535')?.value.trim();if(!name||name.length>160)return toast('Informe um nome com até 160 caracteres.');const item={id:crypto.randomUUID(),name,quantity:1,weight:0,equipped:false,equipType535:slot};if(persistEquipment535(()=>playState().inventory.push(item)))requestEquip535(item.id,slot);}

