function libFacts537(rows){return `<dl class="lib-facts537">${rows.filter(r=>r[1]!==undefined&&r[1]!==null&&r[1]!=='').map(([k,v])=>`<div class="${String(v).replace(/<[^>]*>/g,'').length>70?'lib-fact-wide537':''}"><dt>${esc(k)}</dt><dd>${v}</dd></div>`).join('')}</dl>`;}
