function librarySection537(section){if(!LIB_SECTIONS537[section])return;library537.section=section;library537.query='';library537.category='Todas';renderRulesMenu();document.querySelector('#rules-dialog')?.scrollTo({top:0});}
const rulesMenuBefore537=renderRulesMenu;
renderRulesMenu=function(){const root=document.querySelector('#rules-menu-body');if(!root)return;if(library537.section==='all'){rulesMenuBefore537();root.insertAdjacentHTML('afterbegin',libNav537());return;}root.innerHTML=libNav537()+`<div class="library537" data-native-pt444="true">${library537.section==='home'?libHome537():library537.section==='classes'?libClass537():libList537()}</div>`;enhanceSelects(root);};
const openRulesBefore537=openRulesMenu;
